def _criteria_table(rubric):
    # Public criteria and weights may be shared; anchored score guidance stays evaluator-side.
    return '<h2>Public assessment criteria</h2><p>This task receives a manual, evidence-based score out of 100. Reviewers inspect the submitted artifacts blind to model identity. The criterion weights below describe the work that matters; they do not supply judgments about the inputs.</p><table><thead><tr><th>Criterion</th><th>Weight</th></tr></thead><tbody>'+''.join(f'<tr><td>{html.escape(c["name"])}</td><td>{c["weight"]}</td></tr>' for c in rubric)+'</tbody></table>'


def _criterion(cid, name, weight, zero, middle, full):
    return {'id':cid, 'name':name, 'weight':weight, 'anchors':{'0':zero, '2':middle, '4':full}}


def _task(tid,title,difficulty,capabilities,body,rubric,essential,artifacts,modality=('text',),budget=2700,track='research'):
    intro = f'<h1>{tid} · {html.escape(title)}</h1><p>V1.0 · {track} track · difficulty {difficulty}/5 · suggested budget {budget//60} minutes.</p>'
    contract = '''<div class="note"><strong>Working contract.</strong> This is a self-contained candidate task. Work only from the supplied materials; cite embedded source identifiers and locations. You may use local libraries and code. Do not fetch additional papers, assets, fonts, services, or model outputs. State any local runtime limitation. All scientific examples and numerical fixtures created by the benchmark are synthetic and are labelled as such. No hidden answer file is needed.</div>'''
    outputs='<h2>Submission contract</h2><p>Place the following durable files in your submission directory. Use relative local links and include commands and dependency versions needed to regenerate outputs. The written work should stand on its own; screenshots alone do not replace editable sources.</p><ul>'+''.join('<li><code>'+html.escape(a)+'</code></li>' for a in artifacts)+'</ul>'
    gates='<h2>Core requirements</h2><p>These are reported individually as met, not met, or not assessable. A high numeric score does not override a failed core requirement.</p><ul>'+''.join('<li>'+html.escape(g['requirement'])+'</li>' for g in essential)+'</ul>'
    content='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+html.escape(tid+' '+title)+'</title><style>'+CSS+'</style></head><body><main>'+intro+contract+body+outputs+gates+_criteria_table(rubric)+'</main></body></html>'
    observed = {
        'R01':['figure.svg','figure.png'],
        'R02':['figure.svg','figure.png','alternative-scale.png'],
        'R03':[], 'R04':[],
        'R05':['paired-demonstration.svg','colour-diagnostic.svg'],
        'R06':['evidence-map.svg','evidence-map.png','comparison.html'],
        'X01':['dashboard.html'], 'X02':['explainer.mp4'], 'X03':['sound-bed.wav'],
    }[tid]
    optional = ['listening-preview.mp3'] if tid == 'X03' else []
    return dict(id=tid,title=title,track=track,difficulty=difficulty,capabilities=capabilities,format='html',content=content,rubric=rubric,essential=essential,required_artifacts=artifacts,optional_artifacts=optional,modal_observation_artifacts=observed,modality=list(modality),time_budget_s=budget)


def _style_refs():
    chosen=[('P1','weissgerber2015',2),('P2','rougier2014',7),('P3','crameri2020',3)]
    articles={a['id']:a for a in _articles()}
    out='<h2>Actual offline style references</h2><p>Inspect each whole image and its caption. They are supplied as learning references, not as templates to trace. Your new data and visual grammar may require different axes or panels. A reference can contain both a useful design choice and a limitation.</p>'
    for sid,stem,n in chosen:
        a=articles[sid]
        blob=base64.b64encode((_SOURCE_ROOT/'offline-figures'/f'{stem}-fig{n}.png').read_bytes()).decode()
        from html.parser import HTMLParser
        # Captions are source text extracted during preparation; no external assets.
        import re
        cap=re.search(r'<figure id="'+sid+'-fig'+str(n)+r'">.*?<figcaption>(.*?)</figcaption>',a['html'],re.S).group(1)
        out+=f'<figure><img src="data:image/png;base64,{blob}" alt="{sid} original Figure {n}: style reference"><figcaption><strong>{sid}, Figure {n}.</strong> {cap}<br>Source: {html.escape(a["authors"])} ({a["year"]}), {html.escape(a["title"])}, DOI {a["doi"]}. {a["license"]}: {a["license_url"]}. Display image downsampled and quantized; scientific content retained.</figcaption></figure>'
    return out


def _r01():
    body='''<h2>Research assignment</h2><p>A methods group needs a 180 mm wide figure for a paper about a short conditioning protocol for a synthetic sensor. The reader needs to see what was done, how individual devices changed, and how the transient measurement varies across devices and batches. Learn a coherent visual approach from the three actual figure references below, then make an original three-panel SVG from the supplied experiment and data.</p><h3>Experiment record</h3><p>Twelve independent devices were fabricated in three batches, four devices per batch. Each device was measured once before and once after a 10 minute conditioning step at 25 °C. Values are open-circuit potential in mV. The paired device ID must remain traceable. The separate transient experiment used two independent devices from each batch; at t = 0 s the input was stepped from 0 to 1 in arbitrary units and held through 12 s. Transient outputs are dimensionless normalized responses. Its six device labels are local to this experiment and must not be joined to the paired-potential table. Sampling times are irregular. There is no supplied physical mechanism or statistical significance test.</p><h3>Deliverable specification</h3><ol><li>Write a 350–550 word design note that analyses at least one specific, visible design choice from each of P1 Figure 2, P2 Figure 7 and P3 Figure 3. Identify what you adopted, what you changed for these data, and why. General statements such as “use clean colors” are insufficient.</li><li>Produce one editable SVG with three coordinated panels: the protocol and measurement relationship; paired before/after data; and the six transient series with an appropriate summary if useful. Preserve data identity and units. Choose scales, offsets, annotations and uncertainty summaries deliberately. Explain the independent unit and batch structure. Do not add a mechanism, p-value, sample or measured curve.</li><li>Provide a caption of 160–240 words, define every summary or interval you actually show, and distinguish protocol illustration from data. Show how small absolute changes compare with the operating baseline without disguising the axis.</li><li>Export a PNG preview. Check the figure at 180 mm width, aiming for labels at least 7 pt. SVG text must remain live text and panel/data elements separately editable. Include a short evidence-based visual review covering scientific semantics, final-size legibility and export/editability. Package your editable project or regeneration source and a local README in <code>source.zip</code>; the project may use your chosen vector/design tools.</li></ol>'''+_csv_block('paired.csv',PAIRED)+_csv_block('transient.csv',TIME)+_style_refs()
    rub=[_criterion('R01-A','Scientific encoding and data fidelity',30,'Data, pairing or units are substantially invented or lost.','Most values are represented, but one material design or unit ambiguity remains.','All supplied observations, pairing, batch identity and distinct experimental units are faithfully encoded; summaries are defined and justified.'),_criterion('R01-B','Learning from all three actual figure references',20,'No actual reference analysis or copied artwork replaces the new figure.','All references are named, but analysis is superficial or adoption is poorly connected to the data.','Specific visible choices from all three references are critically analysed and adapted coherently to the new scientific comparison.'),_criterion('R01-C','Scale, comparison and uncertainty judgment',20,'Axes or uncertainty materially distort the scientific comparison.','Scales are plausible but a comparison, baseline or uncertainty definition is unclear.','Scale choices support both small changes and baseline context; comparison, sample unit and uncertainty meaning are explicit and defensible.'),_criterion('R01-D','Composition, typography and accessible visual identity',15,'Important labels or data are unreadable.','Figure is readable at large size but has crowding or inconsistent identities at target size.','Clear reading order, consistent identities, accessible redundant encodings and legible typography work at 180 mm.'),_criterion('R01-E','Editable delivery, caption and targeted visual review',15,'Required vector/source artifacts or meaningful caption are absent.','SVG and preview exist but editability, regeneration or review evidence is incomplete.','Live text, separate editable elements, reproducible source, self-contained caption and concrete inspection evidence support reuse.')]
    return _task('R01','Learn figure style and build an editable scientific SVG',4,['svg','figure_design','reference_learning','scientific_reasoning'],body,rub,[{'id':'data','requirement':'All three original panels use the supplied experiment/data without fabricated scientific content.'},{'id':'refs','requirement':'The design note engages all three supplied actual reference images.'},{'id':'vector','requirement':'An openable SVG with live text and independently editable scientific elements is delivered.'}],['figure.svg','figure.png','caption.md','design-note.md','source.zip','review.md'],('text','image','vector'),3600)


def _r02():
    body='''<h2>Research assignment</h2><p>Build a Python figure for three metrology comparisons. A single plotting default cannot be assumed to work across them. Decide how each axis should encode the scientific question and demonstrate what your choices reveal and conceal.</p><h3>Measurement definitions</h3><ul><li><strong>Paired potential:</strong> twelve independent devices, three fabrication batches, one before and one after observation per device. Instrument resolution is 0.1 mV; no calibration uncertainty is supplied. The question concerns conditioning-induced differences around a roughly 1000 mV operating baseline.</li><li><strong>Dose response:</strong> each row is an independently prepared calibration level, with signal in arbitrary units and supplied expanded uncertainty U, coverage factor k = 2. U describes each reported level, not the spread of raw replicates. No raw replicate values or dose uncertainty are supplied. The question concerns both dynamic range and departures from proportional response.</li><li><strong>Blank-corrected panel:</strong> measured negatives and zero are valid signed estimates after background subtraction. Rows marked left_censored have no numerical point estimate: all that is reported is signal &lt; limit_au. The detection threshold is 0.05 au for every sample. The blank correction can yield negative estimates; missing censored values are not zero. Samples are separate observations; no population distribution is specified.</li></ul><h3>Work</h3><ol><li>Write <code>plot.py</code> using Python and local plotting libraries. Generate a main multi-panel figure plus one compact alternative-scale diagnostic. Include enough of the data to evaluate small paired differences, the large dose-response range, and the signed/censored panel.</li><li>Write a scale-decision table with one row per axis. State the scientific comparison, chosen mapping and limits, what zero means, and the reason for accepting or rejecting linear, log, offset/zoom, difference, or symlog representations as applicable. Log scaling is a decision to justify; you do not receive credit simply for using it. Do not silently drop, clip, replace or take absolute values of observations to make a transformation work.</li><li>Calculate a reproducible summary of paired change that respects device identity. For the calibration plot, preserve the supplied interval definition. Represent censored observations separately from measured values. Any sensitivity calculation involving substituted censored values must be labelled as a sensitivity assumption, with the original records still visible.</li><li>Provide an interpretable caption and a brief review at the intended 180 mm figure width. State numerical and inferential limits of these fixtures and your chosen diagnostic.</li></ol>'''+_csv_block('paired.csv',PAIRED)+_csv_block('dose_response.csv',DYNAMIC)+_csv_block('blank_corrected.csv',SIGNED)
    rub=[_criterion('R02-A','Data parsing, observation status and measurement semantics',25,'Censored, signed or paired observations are corrupted.','Data generally survive but a status or uncertainty definition is ambiguous.','Every row, pairing, status, unit and expanded-uncertainty definition survives the complete workflow.'),_criterion('R02-B','Purposeful scale choices for nearby and broad-range values',25,'A blanket scale rule produces misleading comparisons or drops data.','Scale choices are plausible but the rationale or baseline comparison is incomplete.','Axis-specific decisions explain absolute/relative comparisons, baseline, zero and dynamic range, with a useful diagnostic revealing tradeoffs.'),_criterion('R02-C','Numerical summaries and uncertainty treatment',20,'Summary calculations or error definitions are materially wrong.','Main summaries are usable but limited reproducibility or one uncertainty ambiguity remains.','Paired summaries, interval rendering and any sensitivity assumptions are numerically traceable and scientifically defensible.'),_criterion('R02-D','Scientific readability and caption',15,'Important information is unreadable or unexplained.','Most labels and caption are usable with some omissions at final size.','The figure and caption explain units, experimental unit, intervals, censoring, limits and visual encodings at final size.'),_criterion('R02-E','Runnable Python and transparent decisions',15,'Source cannot regenerate the outputs.','Source runs with manual intervention or incomplete environment/decision records.','A documented local command reproduces vector/raster outputs, summary table and scale-decision record without network access.')]
    return _task('R02','Plot nearby values, dynamic range and censored measurements',4,['python','plotting','metrology','scale_selection','censoring'],body,rub,[{'id':'signed','requirement':'Signed, zero and censored observations remain distinguishable without silent numeric substitution or deletion.'},{'id':'axes','requirement':'Scale choices are made separately for the supplied scientific comparisons and justified.'},{'id':'run','requirement':'Python source and actual generated plot artifacts are delivered.'}],['plot.py','requirements.txt','figure.svg','figure.png','alternative-scale.png','summary.csv','scale-decisions.md','caption.md'],('text','image','vector'),3600)


def _r03():
    draft='''In the rapidly evolving landscape of sensor science, conditioning emerges as a pivotal strategy for unlocking robust device performance. Here, we delve into a comprehensive assessment of twelve independent devices fabricated across three batches, with four devices in each batch. Each device was measured once before and once after a ten-minute conditioning step at 25 °C. The potential increased by 1.2 mV on average, from 1000.4 to 1001.6 mV, and the two-sided paired test gave p = 0.08. This demonstrates a transformative and statistically significant enhancement.\n\nIt is important to note that the measurements were recorded to 0.1 mV, while the instrument's calibration uncertainty was not available. The same devices were measured twice, and no new device was introduced after conditioning. A separate experiment comprised six independent devices, two from each batch. The input was stepped at zero seconds and held for twelve seconds, during which the normalized signal approached unity. It is not merely a response; it is a testament to the stability of the system. No measurements were made after twelve seconds. These findings underscore the vast potential of this approach for long-term deployment and establish the conditioning mechanism. Taken together, the results reveal small short-term changes under the tested conditions. Future work should include calibration checks and longer observation windows.'''
    body='''<h2>Editing assignment</h2><p>A collaborator wants the following English manuscript passage to read naturally and precisely. Edit it conservatively for a methods/results audience. The task is editorial: improve the prose while preserving the scientific record and handling unsupported claims transparently. No AI detector, detector score or promise of “undetectability” is part of the task.</p><h3>Author-approved factual record</h3><p>The numbers in this record belong to this editing task and must not be recomputed from another benchmark question. There were twelve independent devices, three batches, four devices per batch, paired once before and once after a 10 minute conditioning step at 25 °C. Rounded group means were 1000.4 and 1001.6 mV; the mean paired increase was 1.2 mV. The author reports a two-sided paired test with p = 0.08 but has not supplied the test family, statistic or interval. Measurements were recorded to 0.1 mV; calibration uncertainty is unknown. A separate six-device transient experiment had two devices per batch; input was stepped at 0 s and held through 12 s. The normalized response approached unity. No later times, mechanism experiment, long-term stability data, or deployment test were collected. The author intends to propose calibration checks and longer observation windows as future work. No citation has been supplied.</p><h3>Draft to edit</h3><pre>'''+html.escape(draft)+'''</pre><h3>Deliverables</h3><ol><li>Provide a polished 180–250 word English passage suitable for the manuscript. You may reorganize sentences and remove repetition. Keep the quantitative record, experimental units, pairing, missing uncertainty, temporal limits and future-work status intact. Resolve unsupported wording through a clearly documented editorial change or a specific author query; do not create new evidence.</li><li>Create a fact ledger with one row per material claim. Record the original wording or claim ID, factual status, edited location and disposition: preserved, clarified, removed as unsupported, or queried. Include numbers, uncertainty, scope, causality and significance claims.</li><li>Provide a short edit memo explaining the highest-impact changes and any unresolved author queries. Distinguish language editing from scientific verification; do not certify results that the supplied record cannot verify.</li></ol>'''
    rub=[_criterion('R03-A','Preservation of scientific facts and scope',35,'Material numbers, design, uncertainty or limits are invented or lost.','Most facts survive but one material qualification or design detail is weakened.','Every material fact, quantity, design relationship, uncertainty and temporal limit is preserved or transparently queried.'),_criterion('R03-B','Conservative treatment of unsupported scientific claims',25,'Unsupported significance, mechanism or generalization is retained or strengthened without disclosure.','Some problematic wording is corrected but the disposition or author query is incomplete.','Unsupported claims are handled transparently and proportionately, with precise author queries where required and no invented supporting evidence.'),_criterion('R03-C','Natural, precise English for the stated audience',20,'The prose remains inflated, incoherent or unsuitable for a manuscript.','Readable prose still contains unnecessary staging, repetition or vague claims.','Connected, economical manuscript prose uses specific subjects and verbs, varied natural rhythm and appropriate scientific qualification.'),_criterion('R03-D','Auditable claim ledger',15,'No useful claim ledger exists to audit preservation of the scientific record.','A ledger covers numbers but omits causal, uncertainty or scope claims.','A complete and navigable ledger ties original claims to edits, factual status and transparent dispositions.'),_criterion('R03-E','Editorial boundary and deliverable discipline',5,'The output claims verification or detector success.','The boundary is implied but queries or length constraints are poorly handled.','All deliverables meet scope and length, distinguish editing from validation, and make remaining author decisions explicit.')]
    return _task('R03','Conservative English prose editing with a fact ledger',3,['scientific_editing','english','fact_preservation','humanization'],body,rub,[{'id':'facts','requirement':'Material quantitative and experimental facts remain faithful to the approved record.'},{'id':'claims','requirement':'Unsupported significance, causality and duration claims are handled explicitly without adding evidence.'},{'id':'ledger','requirement':'A claim-by-claim fact ledger accompanies the edited passage.'}],['edited.md','fact-ledger.csv','edit-memo.md'],('text',),1800)


def _fixture_figure():
    svg=(_SOURCE_ROOT/'synthetic'/'input-figure.svg').read_text(encoding='utf-8')
    svg=svg[svg.index('<svg'):]
    return '<figure>'+svg+'''<figcaption><strong>Input Figure F1. Benchmark-created synthetic measurements, not published sensor data.</strong> (a) Each line joins one independent device measured before and after a 10 minute conditioning step at 25 °C. Twelve devices were fabricated in three batches (blue B1, orange B2, green B3; four devices per batch). (b) A separate experiment measured six independent devices, two from each batch, after an input step at t = 0 s. Thin coloured lines are device responses, the dark curve is the across-device arithmetic mean, and shading is ±1 sample SD across the six devices at each time, not a confidence interval. Device IDs in the two experiments are not linked. The final observation was at 12 s. Figure width is 180 mm. This figure is an input to analyse, not an answer to the writing assignment.</figcaption></figure>'''


def _r04():
    body='''<h2>Manuscript assignment</h2><p>Write a coherent results paragraph and a discussion paragraph for a short paper, using the actual embedded Figure F1, its underlying tables and the experiment record. The intended audience works on measurement methods and should be able to distinguish an observation from a proposed explanation.</p><h3>Experiment record and rough author notes</h3><p>The paired and transient datasets describe two distinct synthetic experiments. Conditioning lasted 10 min at 25 °C. Potential readings were recorded to 0.1 mV; calibration uncertainty and long-term drift are not available. No control group, randomization, blinded assessment, mechanistic experiment, failure test or post-12 s observation was supplied. Device is the independent unit for the provided summaries; batch clustering may limit generalization. There is no preregistered hypothesis or supplied inferential test.</p><pre>Rough notes, to evaluate rather than accept verbatim:
- after treatment potential seems higher, “all devices improve”
- effect is small compared with 1000 mV baseline; need a useful number
- curves go to one by 12 s, perhaps conditioning creates stable transport paths
- three batches show reproducibility, could claim universal stability?
- maybe fit a response time? say clearly what we can resolve
- distinguish mean and spread; connect the figure panels without merging experiments
- next experiment should distinguish mechanism from short-term response</pre><h3>Work</h3><ol><li>Read both panels at the final size and cross-check their data. Write a 180–260 word Results paragraph that refers explicitly to Figure F1a/F1b and uses at least three relevant, reproducible quantitative statements. Use an analysis appropriate to the sampling and pairing. Do not introduce an inferential result merely because a test is available in a library.</li><li>Write a 200–300 word Discussion paragraph that explains the importance of the observations at their actual scale, separates plausible interpretations from demonstrated mechanisms, and proposes one discriminating follow-up measurement with a predicted outcome under two alternatives.</li><li>Write a revised 130–190 word figure caption. Define the independent unit, panels, batch identities and interval meaning without claiming measurements absent from the record.</li><li>Provide a compact claim-evidence table: claim, exact panel/table location, supporting calculation, status (observation, inference, hypothesis, or unsupported), and scope limit. Include the rough notes you decline to adopt. Supply the small Python calculation script and its output table. Explain any fitted quantity, assumptions and identifiability limits if you choose to fit one.</li></ol>'''+_fixture_figure()+_csv_block('paired.csv',PAIRED)+_csv_block('transient.csv',TIME)
    rub=[_criterion('R04-A','Quantitative fidelity to the actual figure and data',30,'The text misstates observations or invents numerical results.','Most values are traceable but a quantitative comparison or unit is incomplete.','Three or more scientifically useful numerical statements are correct, traceable to calculations and tied to the actual panels.'),_criterion('R04-B','Reasoning across observation, interpretation and mechanism',25,'Hypotheses or short-term observations are promoted to established mechanism or durability.','Interpretation is mostly restrained but an evidential boundary or experiment relationship remains unclear.','Results, inference and hypotheses are explicitly distinguished, experiments remain distinct and a discriminating follow-up has meaningful alternative predictions.'),_criterion('R04-C','Manuscript argument and readable English',20,'Paragraphs are disconnected, generic or unsuitable for a paper.','The narrative is understandable but repetitive or weakly organized around the scientific question.','Each paragraph has a clear scientific purpose and connected argument, with precise language and appropriately bounded significance.'),_criterion('R04-D','Caption, units, interval and experimental structure',10,'Caption materially misdefines the figure.','Caption is usable but omits one important definition or scope limit.','Caption accurately and independently explains both panels, independent units, batch encodings and interval definitions.'),_criterion('R04-E','Claim audit and reproducible numerical support',15,'No usable evidence table or calculation source exists.','Most claims map to sources but some rejected notes or calculations are not auditable.','A complete claim map distinguishes adopted and rejected notes, supports calculations with runnable code and states unresolved scientific limitations.')]
    return _task('R04','Write results and discussion from an embedded figure',4,['scientific_writing','figure_reading','quantitative_reasoning','claim_audit'],body,rub,[{'id':'figure','requirement':'The prose directly interprets both actual embedded panels and respects their distinct experiments.'},{'id':'science','requirement':'No unmeasured mechanism, long-term performance or invented inferential result is stated as established.'},{'id':'trace','requirement':'Quantitative claims are accompanied by a claim-evidence map and reproducible calculations.'}],['manuscript.md','caption.md','claim-evidence.csv','calculations.py','calculated-summary.csv'],('text','image'),3000)


REPLICATION_PAIRS=[('variant','unit','before','after'),*[(v,f'U{i+1}',b,a) for v,afters in [('A',[2,3,4,5,6,7,8,9]),('B',[9,8,7,6,5,4,3,2])] for i,(b,a) in enumerate(zip([1,2,3,4,5,6,7,8],afters))]]
LAB_FIXTURE=[('palette','index','L','a','b'),*[(name,i,*row) for name,rows in [('S',[(10,0,0),(20,0,0),(30,0,0),(40,0,0),(50,0,0),(60,0,0)]),('T',[(10,0,0),(12,0,0),(25,0,0),(55,0,0),(58,0,0),(60,0,0)])] for i,row in enumerate(rows)]]


def _r05():
    body='''<h2>Close reading and partial method reproduction</h2><p>A research group wants to design a transparent figure workflow for small experimental datasets. Read P1–P3 in the offline reading room, including the supplied P1 S1 methods/results. Your work must show how each paper argues, which methods are actually described, and what can be implemented from this source packet.</p><h3>Reading products</h3><ol><li>Create three source cards of 220–320 words each. For each paper record its question, publication type, evidence or example type, unit of analysis, main methodological steps, central claim and boundary. Distinguish an empirical audit from design guidance or a methods demonstration where warranted by the text. Reconcile the sampling stages and denominators of any numerical prevalence you report, using the supplied supplement when relevant.</li><li>Create a keyword glossary with 10–14 terms grounded in the papers. Define terms operationally in this context and give an exact section/figure/table pointer. Include terms about independent units, uncertainty, colour difference and perceptual ordering; do not treat similar terms as automatically interchangeable.</li><li>Build a reasoning table with at least six links: three explicit source arguments and three implicit premises you infer. Each row needs a source location, premise, inference, conclusion, how it could fail, and whether the connection is stated or your reconstruction. Do not present your implicit reconstruction as a quotation or an author claim.</li><li>Write a 500–750 word implementation plan for a new local figure workflow. Map steps to source locations; specify inputs, transformations, outputs, checks, and limits. Identify missing original data, code or supplementary definitions that prevent a larger reproduction. Choose one unresolved ambiguity in the supplied methods and state how you would document or test the choice.</li></ol><h3>Bounded partial reproduction: two small methods</h3><p>Use the supplied synthetic fixtures only. This is a partial reproduction of visual/statistical demonstrations, not a rerun of the papers' empirical audits, colour-map optimization, observer experiments or archived code. Both fixture tables are benchmark-created and have no empirical status.</p><ol><li><strong>Paired-data demonstration:</strong> implement a Python routine that compares the two labelled variants in <code>replication_pairs.csv</code>. Compute marginal means and sample SDs, paired differences and their summaries. Produce a plot showing what is and is not visible from marginal summaries versus preserved pairing, and explain the connection and limits relative to P1's relevant figure. Unit labels are local to each variant.</li><li><strong>Colour-distance demonstration:</strong> implement the adjacent-coordinate distance expression printed in P3's main Methods using <code>lab_fixture.csv</code>. Report adjacent distances, normalized cumulative distance at each index, and deviation from an evenly spaced index. Draw a diagnostic for S and T. State exactly which expression and coordinates you implemented, distinguish the formula as printed from any similarly named metric, and avoid treating this artificial coordinate calculation as a colour-vision validation. The coordinate table is already in a stated L,a,b space; it is not RGB. No external palette package or conversion is required.</li><li>Provide executable local code, the computed tables and figures. Write a 250–400 word reproduction note tying each implemented operation to a source location, showing one numerical consistency check per method, and stating what was not reproduced. Do not claim to have executed unavailable author code.</li></ol>'''+_csv_block('replication_pairs.csv',REPLICATION_PAIRS)+_csv_block('lab_fixture.csv',LAB_FIXTURE)+_article_block()
    rub=[_criterion('R05-A','Accurate close reading and methodological scope',25,'Cards or glossary materially misrepresent the supplied papers.','Broad conclusions are usable but units, denominators, paper types or method scope are incomplete.','All three papers are read accurately with local evidence pointers, appropriate units and denominators, and explicit limits on supplied material.'),_criterion('R05-B','Explicit and implicit scientific reasoning',20,'Author claims and inferred premises are conflated or unsupported.','Some logical links are useful but failure modes or inference status are vague.','Six or more precise, grounded links distinguish stated arguments from reconstructed premises and explain meaningful failure conditions.'),_criterion('R05-C','Actionable source-grounded implementation plan',15,'The plan is generic or assumes unavailable materials.','A plausible plan maps some steps to sources but leaves interfaces or checks vague.','The plan specifies actionable inputs, transformations, outputs and checks; source gaps and one consequential ambiguity are handled transparently.'),_criterion('R05-D','Correct bounded partial reproduction',25,'Required method implementations are missing or scientifically mislabelled.','Both methods are partly implemented, but a calculation, diagnostic or source-to-code link is weak.','Both fixture methods yield traceable correct calculations and useful diagnostics, with exact source-to-code links and faithful metric/coordinate labels.'),_criterion('R05-E','Reproducibility and calibration of conclusions',15,'Artifacts cannot be run or synthetic work is claimed as full paper replication.','Artifacts are mostly runnable but checks, environment or boundaries are incomplete.','Documented local execution regenerates tables and figures, numerical checks are meaningful, and conclusions remain explicitly limited to these partial synthetic demonstrations.')]
    return _task('R05','Read three papers, reconstruct their logic and reproduce bounded methods',5,['literature_reading','methods_analysis','implicit_reasoning','python','partial_replication'],body,rub,[{'id':'three','requirement':'All three supplied papers and the relevant supplied P1 methods supplement are used with identifiable source locations.'},{'id':'two','requirement':'Both partial methods are implemented and produce actual numerical and graphical artifacts.'},{'id':'scope','requirement':'The submission clearly distinguishes source claims, inferred logic, synthetic demonstrations and unavailable full-replication components.'}],['source-cards.md','keywords.csv','reasoning-map.csv','implementation-plan.md','replicate.py','requirements.txt','paired-summary.csv','colour-distance.csv','paired-demonstration.svg','colour-diagnostic.svg','reproduction-note.md'],('text','image','vector'),5400)


def _r06():
    body='''<h2>Critical mini-review assignment</h2><p>Write a focused mini-review for experimental researchers: <em>How should a figure preserve the evidence needed to judge a small experimental study?</em> Use the three actual supplied papers as a closed evidence set. The review should connect sampling and uncertainty to visual encoding and colour, while keeping each paper's evidence type, conditions and limitations visible.</p><h3>Required scientific products</h3><ol><li>Write 800–1100 words of connected English review prose, including a short opening that states the review question, a synthesis across the sources, a discussion of at least two conditional tradeoffs or tensions, and a practical research agenda. Organize by scientific questions rather than one summary paragraph per paper. Distinguish source-supported evidence, normative recommendations and your synthesis. Do not turn an audit in one field and time window into a universal prevalence claim or treat design examples as observer experiments.</li><li>Deliver an original editable SVG evidence map with a caption. It should connect evidence sources and study/measurement characteristics to visual choices and limits. Use explicit relation labels where needed; distinguish observed evidence, recommendations and untested assumptions visually. Every source-derived claim in the map needs a P1/P2/P3 pointer. This is a reasoning figure, not a decorative row of paper icons. Include a legible PNG preview at 180 mm width.</li><li>Provide a comparative table, in CSV and in a reader-friendly rendered form. Use at least eight scientifically useful columns including source, question, evidence type, unit/material examined, method, supported conclusion, conditions/limitations and implication for a figure workflow. Cite exact source locations; do not fabricate commensurate performance scores across unlike papers.</li><li>Supply a claim-evidence ledger linking at least 12 substantive review/table/figure claims to exact sections, figures or supplement locations. Mark your own synthesis separately from direct author claims; if the source does not support a desired claim, narrow it or identify the gap.</li><li>Include a valid reference list for all three papers with authors, year, title, journal and DOI, plus machine-readable BibTeX. Use only this closed evidence set as direct literature support. A reference merely appearing in an embedded paper's bibliography has not itself been read and may not be cited as if independently checked. Figure adaptations require source credit, license and a change statement.</li></ol><h3>Review standard</h3><p>The editor wants an argument whose conclusions can be audited across text, figure, table and references. State an explicit limit on what this closed, purposively selected three-paper set can establish. Do not claim a systematic literature search or comprehensive coverage. Keep the distinction between readability, statistical adequacy and physical/biological mechanism clear.</p>'''+_article_block()
    rub=[_criterion('R06-A','Critical scientific synthesis and conditional conclusions',25,'The review is a list of unsupported summaries or overgeneralizations.','Sources are connected, but conditions, tensions or evidence types are not consistently distinguished.','A coherent cross-source argument preserves evidence type, conditions and scope, examines real tradeoffs and derives a bounded research agenda.'),_criterion('R06-B','Claim-level evidence and valid references',25,'Sources or citations are invented, inaccurate or do not support central claims.','Most claims and references are valid but location-level support or synthesis labels are incomplete.','Substantive claims across all artifacts map to exact supporting source locations, synthesis is labelled, and bibliographic records and DOIs are accurate.'),_criterion('R06-C','Scientific evidence map and editable visual delivery',20,'The figure is decorative, scientifically misleading or not editable.','A useful map exists but relations, provenance, uncertainty or final-size readability are incomplete.','An original, legible editable map explains meaningful relationships, distinguishes evidence status and makes source provenance and limits clear.'),_criterion('R06-D','Comparative table and cross-artifact consistency',15,'The table is absent or compares unlike sources with fabricated scores.','Required columns exist but some entries or cross-artifact statements conflict.','The table makes condition-aware comparisons with exact locations and remains consistent with the review and figure without artificial commensurability.'),_criterion('R06-E','Readable scholarly delivery and honest review scope',15,'The work is incoherent or falsely claims comprehensive/systematic review.','Prose is usable but repetitive, poorly scoped or incomplete in delivery.','Connected review prose, captions and deliverables stand alone, satisfy constraints and explicitly bound the closed evidence set.')]
    return _task('R06','Write a mini-review with an evidence SVG, comparative table and citations',5,['review_writing','evidence_synthesis','svg','tables','citation_audit'],body,rub,[{'id':'evidence','requirement':'All central scientific claims are supported by supplied sources or clearly identified as bounded synthesis.'},{'id':'artifacts','requirement':'Review prose, an editable scientific SVG, a comparative table and a valid three-paper reference list are delivered.'},{'id':'scope','requirement':'No invented citation, unperformed systematic search or unsupported claim of comprehensive coverage is presented.'}],['mini-review.md','evidence-map.svg','evidence-map.png','figure-caption.md','comparison.csv','comparison.html','claim-evidence.csv','references.bib','review-notes.md'],('text','image','vector'),5400)


def _optional_note(modality):
    return f'<div class="note"><strong>Optional capability track.</strong> Enable this task only when the candidate environment can produce and reviewers can inspect actual {modality}. Report capability and review coverage separately from the six-task research score. If the modality is unavailable, return <code>capability.json</code> with status <code>unavailable</code> and a concrete reason; the task is excluded from the enabled-track denominator. Missing modality must never be silently converted to zero or claimed as completed from a text-only plan.</div>'


def _x01():
    body=_optional_note('interactive local HTML')+'''<h2>Build an offline scientific dashboard</h2><p>Make a single self-contained HTML file for a lab meeting about these synthetic metrology measurements. The dashboard should let a researcher explore rather than merely admire the data. No server, package download, CDN, remote font, external image or network request may be required.</p><ol><li>Show paired potential, broad-range calibration and signed/censored measurements with correct units, independent units and status definitions. Embed all input data in the HTML; include a local CSV download action.</li><li>Provide useful batch filtering for paired data, a clearly labelled before/after or difference comparison, and scale controls appropriate to the calibration panel. Preserve signed and censored values in any available scale mode; explain disabled choices locally.</li><li>Update summaries and displayed sample counts consistently with filters. Make resets visible and preserve pairing. Avoid implying precision or population inference absent from the data.</li><li>Provide keyboard-operable controls, meaningful text alternatives or a data table, responsive layout, and a print view. Include a short reproducibility and manual interaction checklist. Verify actual interactions, not merely the presence of buttons.</li></ol><p>Paired devices are independent within three batches; paired readings have 0.1 mV resolution with no calibration uncertainty supplied. Dose-response intervals are expanded uncertainty U with k = 2. Signed measurements are valid blank-corrected estimates; blank records marked left_censored indicate only signal &lt; 0.05 au and have no point estimate.</p>'''+_csv_block('paired.csv',PAIRED)+_csv_block('dose_response.csv',DYNAMIC)+_csv_block('blank_corrected.csv',SIGNED)
    rub=[_criterion('X01-A','Scientific fidelity and scale/status handling',30,'Interactions corrupt pairing, signs, censoring or uncertainty.','Most data are correct but one scale/status ambiguity remains.','All controls preserve scientific meaning, pairing, units, status and interval definitions.'),_criterion('X01-B','Useful, correct interactions',25,'Controls are absent or do not affect the actual data.','Basic controls work but summaries, resets or filters are inconsistent.','Filtering, comparison and scales work coherently, with correct visible counts, summaries and reset behavior.'),_criterion('X01-C','Readability, accessibility and responsive layout',20,'The dashboard is unreadable or inoperable for common users.','Usable layout has accessibility or small-screen limitations.','Clear scientific views, keyboard controls, alternative table/text, responsive layout and print output support practical use.'),_criterion('X01-D','Self-contained offline implementation',15,'The file requires a network or server to function.','Mostly offline with incomplete downloads or packaging.','One HTML embeds all dependencies/data and runs locally with working exports and no network requests.'),_criterion('X01-E','Verification and documented limits',10,'No actual interaction verification is provided.','A checklist exists but evidence or scientific limits are thin.','Concrete local interaction checks cover key states and identify meaningful numerical and runtime limits.')]
    return _task('X01','Self-contained interactive scientific HTML dashboard',4,['html','javascript','data_visualization','interaction'],body,rub,[{'id':'offline','requirement':'One HTML file actually works offline with embedded data and no external dependencies.'},{'id':'interactive','requirement':'Filtering or scale interactions update the visible data and summaries correctly.'},{'id':'science','requirement':'Pairing, signed values, censoring and uncertainty semantics remain intact.'}],['dashboard.html','verification.md','capability.json'],('text','image','interactive_html'),3600,'optional')


def _x02():
    body=_optional_note('video and timed captions')+'''<h2>Produce a short evidence-based science video</h2><p>Create a 45–60 second English explainer for beginning experimental researchers: <em>What can a paired-data plot reveal that a mean-only view can hide?</em> Use the supplied synthetic pairing fixture and P1 as the main scientific source. You may use other supplied papers for design decisions. Deliver actual encoded video, not only a script or storyboard. A silent video with complete burned-in or accompanying captions is acceptable; narration is optional and must not be claimed if absent.</p><ol><li>Plan a small number of scenes with an understandable visual progression from the experimental unit to marginal summaries and preserved pairing. Distinguish synthetic illustration from an empirical result. Keep axis labels and observation identities readable at 1280×720 or higher.</li><li>Produce an MP4 of 45–60 s, H.264-compatible, at 24–30 fps. Use original vector/text/plot assets or the licensed supplied figures with required credit and transformation statements. Do not fetch stock assets or use unlicensed music. Do not imply that the synthetic fixture reproduces the original audit.</li><li>Provide a transcript and synchronized SRT captions saved as <code>captions.srt</code>, including all spoken scientific content if narration is used. Include an end credit identifying sources and licenses. Avoid essential meaning conveyed solely through colour, sound or rapid animation.</li><li>Provide the editable project or rendering source in <code>source.zip</code>, including a README with the local rendering command, and a scene-to-claim evidence table. Verify duration, frame size, caption timing and final readability from actual frames; identify any omitted modality or limitation.</li></ol>'''+_csv_block('replication_pairs.csv',REPLICATION_PAIRS)+_article_block()
    rub=[_criterion('X02-A','Scientific accuracy and source-grounded narrative',30,'The narrative invents evidence or misrepresents pairing.','Main story is accurate but source limits or synthetic status are unclear.','An accessible story explains the scientific relationship accurately, with explicit synthetic status, proper source scope and no unsupported inference.'),_criterion('X02-B','Visual explanation, pacing and final-size readability',25,'Visuals are unreadable or do not explain the concept.','The idea is understandable but pacing, labels or transitions impede learning.','Purposeful scenes, readable plots and disciplined pacing explain the concept within the actual runtime.'),_criterion('X02-C','Captions and multimodal accessibility',20,'Scientific content is inaccessible without an absent or uncaptioned modality.','Captions exist but timing, completeness or colour-only dependence has issues.','Complete synchronized captions/transcript and redundant visual meaning make the science understandable with available modalities.'),_criterion('X02-D','Actual encoded deliverable and editable source',15,'Only a plan or invalid video is delivered.','Video plays but source, technical specifications or regeneration are incomplete.','Playable compliant video and editable source can be inspected and regenerated locally.'),_criterion('X02-E','Evidence map, credits and media verification',10,'Sources, licenses or actual media checks are absent.','Credits and checks exist but claim links or transformation notices are incomplete.','Scene-level evidence links, accurate credits/licenses and actual duration/frame/caption checks are documented.')]
    return _task('X02','Short scientific explainer video with captions and sources',4,['video','scientific_storytelling','captions','media_verification'],body,rub,[{'id':'actual','requirement':'If enabled, an actual playable 45–60 second video and timed captions are delivered.'},{'id':'grounded','requirement':'Scientific claims are grounded in supplied material and synthetic illustrations are labelled.'},{'id':'rights','requirement':'Supplied assets and original assets have accurate attribution, license and change records.'}],['explainer.mp4','captions.srt','transcript.md','source.zip','scene-evidence.csv','media-checks.md','capability.json'],('text','image','video'),5400,'optional')


def _x03():
    body=_optional_note('instrumental audio')+'''<h2>Compose an original sound bed for a science explainer</h2><p>Create a quiet 32 second instrumental sound bed for a narrated explanation of how a plot preserves evidence. The music should support listening to precise English narration without pretending to encode measured scientific data. Use original composition and synthesis or locally available self-owned samples. Do not imitate a named artist or reuse an existing melody, commercial recording, stock loop or unverified sample.</p><h3>Timeline and narration context</h3><table><tr><th>Time</th><th>Scene and speaking demand</th></tr><tr><td>0–8 s</td><td>Introduce independent devices. Narration is dense and includes numbers.</td></tr><tr><td>8–16 s</td><td>Show a mean-only summary. Calm visual hold with a short pause at 14–15 s.</td></tr><tr><td>16–25 s</td><td>Reveal pairing and individual differences. A gentle transition may mark the reveal at 16 s.</td></tr><tr><td>25–32 s</td><td>State the scientific limitation and show source credits. Resolve without a dramatic claim of discovery.</td></tr></table><h3>Work</h3><ol><li>Deliver an actual original instrumental WAV, 48 kHz PCM, stereo, duration 32.0 ±0.2 s. No speech or lyrics. Use restrained dynamics and no abrupt transient or ending click. Target integrated loudness between −26 and −20 LUFS and true peak no higher than −3 dBTP if your tooling can measure these; report exact measurement methods and do not substitute sample peak for true peak without disclosure.</li><li>Provide editable MIDI, notation or synthesis code in <code>source.zip</code>, including a README with the exact local command to regenerate the piece. Include tempo, meter or free-time structure, instruments, harmonic/melodic design and a cue sheet aligned with the scene timings.</li><li>Provide a short creative rationale, provenance statement for every audio ingredient and a technical report. Explain how texture, register, dynamics and transitions leave room for narration. Report actual duration and clipping checks. Do not claim audibility, narration masking tests or loudness metrics you did not perform. No narration stem is supplied; subjective mixing conclusions must be bounded accordingly.</li><li>Include a 128–256 kbps listening preview if your local encoder is available. If an optional encoder or LUFS tool is unavailable, identify that limitation; lack of an optional metric alone does not erase a valid audio artifact.</li></ol>'''
    rub=[_criterion('X03-A','Original composition and suitability for the brief',30,'No original coherent audio is delivered or the work copies protected material.','The composition is usable but poorly aligned with the quiet explanatory brief.','A coherent original instrumental piece supports the scene structure with restrained musical decisions and a clear narrative purpose.'),_criterion('X03-B','Arrangement, transitions and room for narration',25,'Dense or abrupt audio would obscure the stated narration context.','The arrangement generally supports narration but some register, transient or cue decisions are weak.','Texture, register, dynamics and transitions are purposefully aligned to dense speech, pause, reveal and conclusion, with limitations of an absent narration stem acknowledged.'),_criterion('X03-C','Audio integrity and measured technical delivery',20,'Audio is invalid, clipped or materially fails duration/format.','Playable audio meets core format but has minor integrity or metric/reporting gaps.','Actual audio meets duration/format, has clean boundaries and no clipping, with transparently measured loudness/peak results or specific tool limitations.'),_criterion('X03-D','Editable regeneration and cue alignment',15,'No useful editable source is supplied.','Source exists but regeneration or timing alignment is incomplete.','Editable music/synthesis source, documented local execution and precise cue timings permit revision and regeneration.'),_criterion('X03-E','Provenance and honest listening/measurement claims',10,'Ingredient provenance or measurement claims are fabricated.','Basic provenance exists but some ingredients or verification limits are unclear.','Every ingredient has clear provenance and reports distinguish actual checks, listening judgments and unmeasured properties.')]
    return _task('X03','Original instrumental sound bed for a scientific explainer',4,['audio','music_composition','synthesis','audio_measurement'],body,rub,[{'id':'audio','requirement':'If enabled, an actual openable original instrumental WAV is delivered with the requested core duration and format.'},{'id':'provenance','requirement':'Every musical/audio ingredient is original or has verifiable permitted provenance.'},{'id':'honest','requirement':'Technical and listening claims distinguish actual measurements from unperformed checks.'}],['sound-bed.wav','source.zip','cue-sheet.csv','creative-rationale.md','audio-report.md','capability.json'],('text','audio'),3600,'optional')


def tasks() -> list[dict]:
    """Return six required research tasks and three separate optional capability tasks."""
